mapper.update:
update med_exam_appointment
set status = #{status}
where appointment_no = #{appointmentNo}
  and status != 3

mapper.select:
SELECT a.id, a.patient_name as patientName, a.gender, CONCAT(SUBSTRING(a.phone,1,3),"****",SUBSTRING(a.phone,8,4)) AS phone, CONCAT(SUBSTRING(a.id_card_no,1,3),"***********",SUBSTRING(a.id_card_no,15,4)) AS idCardNo, TIMESTAMPDIFF(YEAR,a.birth_date,NOW()) AS age, a.company, a.status, o.goods_title AS goodsTitle, o.snapshot_id AS snapshotId FROM med_exam_appointment a JOIN trade_order o ON a.order_id = o.order_id
AND a.appointment_date = #{appointmentDate}
AND a.patient_name LIKE CONCAT("%",#{patientName},"%")
AND a.phone = #{phone}
AND a.status = #{status}
ORDER BY a.id DESC

select id, status
from med_exam_appointment
where id_card_no = #{idCardNo}
  and patient_name = #{patientName}
  and gender = #{gender}
  and appointment_date = CURRENT_DATE
limit 1
